#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<long long> a(3 * n);
        for (auto &x: a) {
            cin >> x;
        }
        sort(a.rbegin(), a.rend());
        vector<long long> p(3 * n + 1);
        for (int i = 0; i < 3 * n; i++) {
            p[i + 1] = p[i] + a[i];
        }
        auto calc = [&](int x, int y) {
            return 2 * p[x] + p[x + 2 * y] + 3 * p[3 * n - 2 * x - y];
        };
        long long ans = 0;
        for (int x = 0; x <= n; x++) {
            int lo = 0, hi = n - x;
            auto delta = [&](int y) {
                int v = x + 2 * y;
                int w = 3 * n - 2 * x - y;
                return a[v] + a[v + 1] - 3 * a[w - 1];
            };
            while (lo < hi) {
                int middle = (lo + hi) / 2;
                if (middle < n - x && delta(middle) > 0) {
                    lo = middle + 1;
                }
                else {
                    hi = middle;
                }
            }
            ans = max(ans, calc(x, lo));
        }
        cout << ans << endl;
    }
}
